<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Kanban Board</title>
  <style>
    :root {
      color-scheme: light;
      --background: #f4f6fb;
      --surface: #ffffff;
      --surface-muted: #eef1f6;
      --text: #172033;
      --muted: #657089;
      --border: #dfe4ed;
      --accent: #4f65e8;
      --accent-dark: #3e52ca;
      --danger: #d84255;
      --shadow: 0 10px 28px rgba(23, 32, 51, 0.08);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      background:
        radial-gradient(circle at top left, rgba(79, 101, 232, 0.09), transparent 34rem),
        var(--background);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    button,
    input {
      font: inherit;
    }

    .app {
      width: min(1180px, calc(100% - 32px));
      margin: 0 auto;
      padding: 44px 0;
    }

    .page-header {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 28px;
    }

    .page-header h1 {
      margin: 0;
      font-size: clamp(1.8rem, 4vw, 2.6rem);
      letter-spacing: -0.04em;
    }

    .page-header p {
      margin: 8px 0 0;
      color: var(--muted);
    }

    .add-form {
      display: flex;
      width: min(100%, 460px);
      padding: 5px;
      border: 1px solid var(--border);
      border-radius: 13px;
      background: var(--surface);
      box-shadow: 0 4px 16px rgba(23, 32, 51, 0.05);
    }

    #new-card {
      min-width: 0;
      flex: 1;
      padding: 10px 12px;
      border: 0;
      outline: 0;
      background: transparent;
      color: var(--text);
    }

    #new-card::placeholder {
      color: #929bad;
    }

    #new-card:focus-visible {
      border-radius: 8px;
      box-shadow: inset 0 0 0 2px rgba(79, 101, 232, 0.3);
    }

    #add-card {
      flex: 0 0 auto;
      padding: 10px 17px;
      border: 0;
      border-radius: 9px;
      background: var(--accent);
      color: #fff;
      font-weight: 700;
      cursor: pointer;
      transition: background 150ms ease, transform 150ms ease;
    }

    #add-card:hover {
      background: var(--accent-dark);
    }

    #add-card:active {
      transform: translateY(1px);
    }

    .board {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
      align-items: start;
    }

    .column {
      display: flex;
      min-height: 440px;
      flex-direction: column;
      padding: 16px;
      border: 1px solid var(--border);
      border-radius: 18px;
      background: rgba(238, 241, 246, 0.8);
      transition: border-color 150ms ease, background 150ms ease, transform 150ms ease;
    }

    .column.drag-over {
      border-color: var(--accent);
      background: rgba(79, 101, 232, 0.08);
      transform: translateY(-2px);
    }

    .column-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      padding: 2px 2px 14px;
    }

    .column-header h2 {
      margin: 0;
      font-size: 1rem;
      letter-spacing: -0.01em;
    }

    .count {
      display: inline-grid;
      min-width: 28px;
      height: 28px;
      place-items: center;
      padding: 0 8px;
      border-radius: 999px;
      background: #dde2ec;
      color: #536078;
      font-size: 0.8rem;
      font-weight: 800;
    }

    .card-container {
      display: flex;
      min-height: 360px;
      flex: 1;
      flex-direction: column;
      gap: 11px;
      border-radius: 12px;
    }

    .card {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 12px;
      padding: 16px;
      border: 1px solid rgba(223, 228, 237, 0.9);
      border-radius: 13px;
      background: var(--surface);
      box-shadow: 0 5px 15px rgba(23, 32, 51, 0.07);
      cursor: grab;
      transition: box-shadow 150ms ease, transform 150ms ease, opacity 150ms ease;
    }

    .card:hover {
      box-shadow: var(--shadow);
      transform: translateY(-1px);
    }

    .card:active {
      cursor: grabbing;
    }

    .card.dragging {
      opacity: 0.45;
      transform: rotate(1deg);
    }

    .card-title {
      min-width: 0;
      margin: 0;
      overflow-wrap: anywhere;
      line-height: 1.45;
      font-weight: 600;
    }

    .card-del {
      display: inline-grid;
      width: 28px;
      height: 28px;
      flex: 0 0 28px;
      place-items: center;
      border: 0;
      border-radius: 8px;
      background: transparent;
      color: var(--muted);
      font-size: 1.15rem;
      line-height: 1;
      cursor: pointer;
      transition: color 150ms ease, background 150ms ease;
    }

    .card-del:hover {
      background: #feecef;
      color: var(--danger);
    }

    button:focus-visible {
      outline: 3px solid rgba(79, 101, 232, 0.3);
      outline-offset: 2px;
    }

    @media (max-width: 800px) {
      .app {
        padding-top: 28px;
      }

      .page-header {
        align-items: stretch;
        flex-direction: column;
      }

      .add-form {
        width: 100%;
      }

      .board {
        grid-template-columns: 1fr;
      }

      .column {
        min-height: 230px;
      }

      .card-container {
        min-height: 150px;
      }
    }
  </style>
</head>
<body>
  <main class="app">
    <header class="page-header">
      <div>
        <h1>Kanban Board</h1>
        <p>Organize tasks and move work forward.</p>
      </div>

      <form class="add-form" id="add-form">
        <input
          id="new-card"
          type="text"
          placeholder="Add a new task…"
          aria-label="New card title"
          autocomplete="off"
        >
        <button id="add-card" type="submit">Add card</button>
      </form>
    </header>

    <section class="board" aria-label="Kanban board">
      <section class="column" id="col-todo" data-column="todo">
        <header class="column-header">
          <h2>To Do</h2>
          <span class="count" aria-label="0 cards">0</span>
        </header>
        <div class="card-container" aria-label="To Do cards"></div>
      </section>

      <section class="column" id="col-doing" data-column="doing">
        <header class="column-header">
          <h2>Doing</h2>
          <span class="count" aria-label="0 cards">0</span>
        </header>
        <div class="card-container" aria-label="Doing cards"></div>
      </section>

      <section class="column" id="col-done" data-column="done">
        <header class="column-header">
          <h2>Done</h2>
          <span class="count" aria-label="0 cards">0</span>
        </header>
        <div class="card-container" aria-label="Done cards"></div>
      </section>
    </section>
  </main>

  <script>
    (() => {
      "use strict";

      const STORAGE_KEY = "kanban-board-state";
      const columnNames = ["todo", "doing", "done"];
      const columns = Array.from(document.querySelectorAll(".column"));
      const form = document.getElementById("add-form");
      const input = document.getElementById("new-card");
      let draggedCard = null;

      function createId() {
        if (window.crypto && typeof window.crypto.randomUUID === "function") {
          return window.crypto.randomUUID();
        }
        return "card-" + Date.now() + "-" + Math.random().toString(36).slice(2);
      }

      function createCard(title, id = createId()) {
        const card = document.createElement("article");
        card.className = "card";
        card.id = id;
        card.setAttribute("draggable", "true");

        const titleElement = document.createElement("p");
        titleElement.className = "card-title";
        titleElement.textContent = title;

        const deleteButton = document.createElement("button");
        deleteButton.className = "card-del";
        deleteButton.type = "button";
        deleteButton.textContent = "×";
        deleteButton.setAttribute("aria-label", "Delete " + title);

        deleteButton.addEventListener("click", () => {
          card.remove();
          updateCounts();
          saveBoard();
        });

        card.addEventListener("dragstart", event => {
          draggedCard = card;
          card.classList.add("dragging");
          event.dataTransfer.effectAllowed = "move";
          event.dataTransfer.setData("text/plain", card.id);
        });

        card.addEventListener("dragend", () => {
          card.classList.remove("dragging");
          columns.forEach(column => column.classList.remove("drag-over"));
          draggedCard = null;
        });

        card.append(titleElement, deleteButton);
        return card;
      }

      function updateCounts() {
        columns.forEach(column => {
          const total = column.querySelectorAll(".card-container > .card").length;
          const count = column.querySelector(".count");
          count.textContent = String(total);
          count.setAttribute("aria-label", total + (total === 1 ? " card" : " cards"));
        });
      }

      function saveBoard() {
        const state = {};

        columns.forEach(column => {
          const name = column.dataset.column;
          state[name] = Array.from(column.querySelectorAll(".card")).map(card => ({
            id: card.id,
            title: card.querySelector(".card-title").textContent
          }));
        });

        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
        } catch (error) {
          console.warn("Unable to save the board.", error);
        }
      }

      function loadBoard() {
        let state;

        try {
          const stored = localStorage.getItem(STORAGE_KEY);
          state = stored ? JSON.parse(stored) : null;
        } catch (error) {
          state = null;
        }

        if (!state || typeof state !== "object") {
          updateCounts();
          return;
        }

        columnNames.forEach(name => {
          const cards = Array.isArray(state[name]) ? state[name] : [];
          const container = document.querySelector(
            '.column[data-column="' + name + '"] .card-container'
          );

          cards.forEach(item => {
            if (item && typeof item.title === "string" && item.title.trim()) {
              container.appendChild(
                createCard(item.title, typeof item.id === "string" ? item.id : createId())
              );
            }
          });
        });

        updateCounts();
      }

      form.addEventListener("submit", event => {
        event.preventDefault();

        const title = input.value.trim();
        if (!title) return;

        document.querySelector("#col-todo .card-container").appendChild(createCard(title));
        input.value = "";
        updateCounts();
        saveBoard();
        input.focus();
      });

      columns.forEach(column => {
        column.addEventListener("dragover", event => {
          event.preventDefault();
          event.dataTransfer.dropEffect = "move";
          column.classList.add("drag-over");
        });

        column.addEventListener("dragenter", event => {
          event.preventDefault();
          column.classList.add("drag-over");
        });

        column.addEventListener("dragleave", event => {
          if (!column.contains(event.relatedTarget)) {
            column.classList.remove("drag-over");
          }
        });

        column.addEventListener("drop", event => {
          event.preventDefault();
          column.classList.remove("drag-over");

          const cardId = event.dataTransfer.getData("text/plain");
          const card = draggedCard || document.getElementById(cardId);

          if (card && card.classList.contains("card")) {
            column.querySelector(".card-container").appendChild(card);
            updateCounts();
            saveBoard();
          }
        });
      });

      loadBoard();
    })();
  </script>
</body>
</html>
